create table if not exists public.cp_vip_group_call_queue (user_id uuid primary key references auth.users(id) on delete cascade,requested_at timestamptz not null default now());
alter table public.cp_vip_group_call_queue enable row level security;
revoke all on public.cp_vip_group_call_queue from anon,authenticated;
create policy "deny_vip_group_call_queue_api" on public.cp_vip_group_call_queue for all to authenticated using(false) with check(false);
create or replace function public.request_vip_group_video_match() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); other uuid; tid uuid; cid uuid; used integer:=0; begin if uid is null then raise exception 'Unauthorized'; end if; if not exists(select 1 from public.profiles where id=uid and is_vip=true and (vip_expires_at is null or vip_expires_at>now())) then raise exception 'Active VIP required'; end if; select video_seconds into used from public.cp_vip_group_call_usage where user_id=uid and usage_day=current_date; if coalesce(used,0)>=1800 then raise exception 'Your free video-call time for today is used'; end if; select q.user_id into other from public.cp_vip_group_call_queue q join public.profiles p on p.id=q.user_id where q.user_id<>uid and p.is_vip=true and (p.vip_expires_at is null or p.vip_expires_at>now()) and q.requested_at>now()-interval '2 minutes' order by q.requested_at for update skip locked limit 1; if other is null then insert into public.cp_vip_group_call_queue(user_id) values(uid) on conflict(user_id) do update set requested_at=now(); return jsonb_build_object('status','waiting'); end if; delete from public.cp_vip_group_call_queue where user_id in (uid,other); select id into tid from public.cp_threads where ((owner_id=uid and participant_id=other) or (owner_id=other and participant_id=uid)) and kind='vip_call_match' limit 1; if tid is null then insert into public.cp_threads(owner_id,participant_id,kind,other_alias,blurb) values(uid,other,'vip_call_match','VIP Panda','VIP group video call') returning id into tid; end if; select id into cid from public.start_vip_private_call(tid,'video'); return jsonb_build_object('status','matched','call_id',cid,'thread_id',tid); end $$;
grant execute on function public.request_vip_group_video_match() to authenticated;
revoke execute on function public.request_vip_group_video_match() from anon;